{
  "issues": [
    {
      "issue_id": "SPA-N-001",
      "position": "PUSHBACK",
      "evidence": "Seek a higher general cap supported by the deal risk and diligence"
    },
    {
      "issue_id": "SPA-N-002",
      "position": "PUSHBACK",
      "evidence": "reduce or remove the de minimis; and seek a tipping basket"
    },
    {
      "issue_id": "SPA-N-003",
      "position": "PUSHBACK",
      "evidence": "Reject an 18-month deadline for every claim."
    },
    {
      "issue_id": "SPA-N-004",
      "position": "PUSHBACK",
      "evidence": "Do not apply the general regime to fundamental/title claims."
    },
    {
      "issue_id": "SPA-N-005",
      "position": "PUSHBACK",
      "evidence": "Fraud, deliberate concealment and other non-excludable liability should also be carved out."
    },
    {
      "issue_id": "SPA-N-006",
      "position": "PUSHBACK",
      "evidence": "Reject blanket data-room and public-register disclosure."
    },
    {
      "issue_id": "SPA-N-007",
      "position": "PUSHBACK",
      "evidence": "Reject the broad Buyer-knowledge bar."
    },
    {
      "issue_id": "SPA-N-008",
      "position": "PUSHBACK",
      "evidence": "Do not treat the condition as satisfied merely because written consent is delivered"
    },
    {
      "issue_id": "SPA-N-009",
      "position": "PUSHBACK",
      "evidence": "Do not accept a promise to obtain a release afterward."
    },
    {
      "issue_id": "SPA-N-010",
      "position": "PUSHBACK",
      "evidence": "Treat the bonuses and associated employer costs as Seller-borne transaction expenses or debt-like items that reduce the amount payable to Seller"
    },
    {
      "issue_id": "SPA-N-011",
      "position": "PUSHBACK",
      "evidence": "Require payment and written confirmation of assignment/transfer and all necessary IP rights by Completion"
    },
    {
      "issue_id": "SPA-N-012",
      "position": "PUSHBACK",
      "evidence": "Seek a specific indemnity for incident-related costs and liabilities, outside general caps and time limits"
    },
    {
      "issue_id": "SPA-N-013",
      "position": "PARTIAL",
      "evidence": "The three AUD 110,000 renewals total AUD 330,000. The disclosure does not establish whether they are unavoidable, terminable, accrued or ordinary-course."
    },
    {
      "issue_id": "SPA-N-014",
      "position": "PUSHBACK",
      "evidence": "Carve out specific indemnities and other agreed protections from general limitations and exclusive-remedy language."
    },
    {
      "issue_id": "SPA-N-015",
      "position": "PUSHBACK",
      "evidence": "DD-012 is only the source the Seller relies on for title; it is not a substitute for robust title warranties and Completion evidence."
    },
    {
      "issue_id": "SPA-N-016",
      "position": "PUSHBACK",
      "evidence": "Seek suitable tax and IP warranties, with tailored caps and time periods; consider specific indemnities for identified material exposures."
    }
  ],
  "adopts_framing": false,
  "adopts_framing_evidence": "",
  "names_manipulation": true
}

